update public.plagas p set combate = v.txt
from (values
('abolladura','Tratamiento cúprico en otoño (caída de hoja) y al hinchado de yemas en primavera. Fitosanitarios Sipcam (botella pequeña, disponible en tienda): Oxicloruro de cobre 3 ml/L de agua, 2 aplicaciones separadas 15 días. Mojar bien toda la ramificación.'),
('antracnosis','Retirar hojarasca y frutos momificados. Fitosanitarios Sipcam: Oxicloruro de cobre 3 ml/L en brotación y fungicida polivalente (mancozeb/miclobutanil) 1,5–2 ml/L cada 12–14 días en periodos húmedos.'),
('arana-roja','Aumentar la humedad ambiental y eliminar hojas muy afectadas. Fitosanitarios Sipcam: acaricida de abamectina 0,75–1 ml/L o aceite de parafina 15–20 ml/L; jabón potásico 10–15 ml/L como apoyo. Repetir a los 7–10 días mojando el envés.'),
('bacteriosis-del-nogal','Podar en seco y eliminar restos. Fitosanitarios Sipcam: Oxicloruro de cobre 3 ml/L en brotación, floración y caída de hoja.'),
('botritis','Riego moderado, buena ventilación y retirada de partes podridas. Fitosanitarios Sipcam: fungicida antibotritis 1,5–2 ml/L cada 10–14 días, evitando tratar con fruto próximo a recolección (respetar el plazo de seguridad).'),
('caracoles-y-babosas','Trampas de cerveza, acolchado seco y riego por la mañana. Producto Sipcam: cebo antilimacos granulado esparcido alrededor de la planta (no se diluye); repetir tras lluvias.'),
('chancro-del-castano','Podar y quemar ramas afectadas, desinfectando la herramienta. Fitosanitarios Sipcam: Oxicloruro de cobre 3 ml/L sobre los cortes y pasta cicatrizante.'),
('clorosis-ferrica','Corregir el pH y evitar encharcamiento. Producto Sipcam: quelato de hierro EDDHA, 1–2 g/L en riego (o 20–30 g por árbol adulto), 2 aplicaciones en primavera.'),
('cochinilla','Cepillado de las cochinillas visibles y poda de aireación. Fitosanitarios Sipcam: aceite de parafina 15–20 ml/L (fuera de horas de sol) o insecticida polivalente de deltametrina 0,5–1 ml/L; jabón potásico 10–15 ml/L en ecológico.'),
('cochinilla-algodonosa','Poda de aireación y limpieza de melaza. Fitosanitarios Sipcam: aceite de parafina 15–20 ml/L mezclado con jabón potásico 10 ml/L; repetir a los 15 días.'),
('exceso-de-humedad','Evitar encharcamiento, mejorar drenaje y podar tras la floración. Si aparecen hongos de suelo: fungicida cúprico Sipcam 3 ml/L aplicado al cuello de la planta.'),
('fusarium','Rotación de cultivos, portainjertos resistentes y eliminación de plantas afectadas. Fitosanitarios Sipcam: fungicida de suelo autorizado 2 ml/L regado al pie en trasplante y a los 20 días.'),
('gusano-del-boniato','Trampas de feromonas, suelo bien drenado y rotación larga. Fitosanitarios Sipcam: insecticida de suelo autorizado, 1–1,5 ml/L en el agua de riego antes de la plantación.'),
('hernia-de-la-col','Rotación larga (4 años) y encalado del suelo hasta pH 7. No hay fitosanitario curativo: eliminar y no compostar las plantas afectadas.'),
('hongos-por-exceso-de-riego','Suelo bien drenante y riegos espaciados. Fitosanitarios Sipcam: fungicida cúprico 3 ml/L o fungicida sistémico 2 ml/L regado al cuello, 2 aplicaciones separadas 15 días.'),
('mildiu','Preventivo con caldo bordelés y buena ventilación. Fitosanitarios Sipcam: Oxicloruro de cobre 3 ml/L cada 10–12 días en tiempo húmedo; en ataque fuerte, fungicida sistémico antimildiu 2–2,5 ml/L (máximo 2–3 aplicaciones por campaña).'),
('mildiu-de-la-albahaca','Riego a pie de planta, buena ventilación y recorte de hojas bajas. Fitosanitarios Sipcam: cobre 2–3 ml/L de forma preventiva, respetando el plazo de seguridad antes de consumir la hoja.'),
('mildiu-de-la-cebolla','Rotación y marcos aireados. Fitosanitarios Sipcam: Oxicloruro de cobre 3 ml/L preventivo cada 12 días; fungicida sistémico 2 ml/L si la enfermedad ya está instalada.'),
('mildiu-de-la-lechuga','Evitar mojar la hoja y airear el marco de plantación. Fitosanitarios Sipcam: cobre 2–3 ml/L en preventivo; suspender los tratamientos 15 días antes de la recolección.'),
('minador-de-la-hoja','Retirar hojas minadas y colocar malla antiinsectos. Fitosanitarios Sipcam: abamectina 0,75–1 ml/L o aceite de neem 5 ml/L, 2 aplicaciones separadas 7–10 días.'),
('minador-de-los-citricos','Tratar sobre brotación tierna. Fitosanitarios Sipcam: aceite de neem 5 ml/L o abamectina 0,75–1 ml/L, repitiendo cada 10–12 días mientras dure la brotación.'),
('mosca-blanca','Trampas cromáticas amarillas y limpieza de malas hierbas. Fitosanitarios Sipcam: jabón potásico 10–15 ml/L o insecticida polivalente de deltametrina 0,5–1 ml/L; repetir a los 7 días mojando el envés.'),
('mosca-de-la-fruta','Trampas de captura y recogida de fruta caída. Fitosanitarios Sipcam: cebo atrayente + insecticida polivalente 0,5–1 ml/L aplicado en parcheo (no a todo el árbol) desde el envero.'),
('mosca-de-la-zanahoria','Malla antiinsectos y siembras escalonadas. Fitosanitarios Sipcam: insecticida polivalente de deltametrina 0,5–1 ml/L en los momentos de vuelo (mayo y agosto).'),
('mosca-del-olivo','Trampas cromáticas y de feromona desde julio. Fitosanitarios Sipcam: tratamiento cebo con insecticida polivalente 0,5–1 ml/L o caolín, repitiendo cada 3 semanas.'),
('moteado','Podar para airear la copa y retirar hojarasca. Fitosanitarios Sipcam: cobre 3 ml/L al hinchado de yema y fungicida sistémico (miclobutanil) 1,5–2 ml/L en floración y postfloración.'),
('moteado-del-nispero','Podar para airear y retirar hoja caída. Fitosanitarios Sipcam: cobre 3 ml/L en parada invernal y fungicida sistémico 1,5–2 ml/L en primavera húmeda.'),
('negrilla','Controlar antes el pulgón o la cochinilla, que producen la melaza. Fitosanitarios Sipcam: jabón potásico 15 ml/L para lavar la hoja + aceite de parafina 15 ml/L sobre la plaga causante.'),
('oidio','Airear entre plantas y evitar exceso de nitrógeno. Fitosanitarios Sipcam: azufre mojable 3–5 ml/L (no tratar por encima de 30 ºC) o fungicida sistémico antioídio 1,5–2 ml/L cada 12 días.'),
('oidio-del-roble','Airear la copa y podar chupones. Fitosanitarios Sipcam: azufre mojable 3–5 ml/L en brotación, repitiendo a los 15 días.'),
('oidiopsis','Evitar exceso de humedad y airear el cultivo. Fitosanitarios Sipcam: azufre mojable 3–5 ml/L o antioídio sistémico 1,5–2 ml/L, alternando materias activas.'),
('oruga-de-la-col','Revisar el envés de la hoja y retirar puestas. Fitosanitarios Sipcam: Bacillus thuringiensis 1–2 ml/L al atardecer (respetuoso, sin plazo de espera) o insecticida polivalente 0,5–1 ml/L en ataques fuertes.'),
('pulgon','Fomentar mariquitas y despuntar brotes muy infestados. Fitosanitarios Sipcam: jabón potásico 10–15 ml/L, piretrina natural 1–2 ml/L o insecticida polivalente de deltametrina 0,5–1 ml/L; repetir a los 7 días.'),
('pulgon-ceniciento','Eliminar brotes y hojas enrolladas. Fitosanitarios Sipcam: jabón potásico 15 ml/L o deltametrina 0,5–1 ml/L, mojando muy bien el interior del cogollo.'),
('pulgon-negro','Despunte de brotes tiernos. Fitosanitarios Sipcam: jabón potásico 10–15 ml/L o piretrina natural 1–2 ml/L, 2 aplicaciones separadas 7 días.'),
('pulguilla','Riego frecuente para mantener la humedad y malla fina. Fitosanitarios Sipcam: insecticida polivalente de deltametrina 0,5–1 ml/L al atardecer en los primeros estadios del cultivo.'),
('roya','Rotación de cultivos y retirada de hojas afectadas. Fitosanitarios Sipcam: azufre mojable 3–5 ml/L en preventivo o fungicida sistémico antiroya 1,5–2 ml/L cada 12–14 días.'),
('roya-de-la-judia','Airear el emparrado y no mojar la hoja. Fitosanitarios Sipcam: azufre mojable 3–5 ml/L o fungicida sistémico 1,5–2 ml/L, respetando 7 días de plazo antes de recolectar.'),
('roya-de-la-menta','Cortar a ras en otoño y renovar la mata cada 2–3 años. Al tratarse de planta de consumo en fresco, priorizar el manejo cultural; si se trata, azufre mojable Sipcam 3 ml/L y no consumir en 15 días.'),
('roya-del-puerro','Marcos amplios y evitar el exceso de nitrógeno. Fitosanitarios Sipcam: azufre mojable 3–5 ml/L o fungicida sistémico 1,5–2 ml/L cada 14 días.'),
('roya-del-sauce','Podar ramas afectadas y airear la copa. Fitosanitarios Sipcam: cobre 3 ml/L en parada vegetativa y azufre mojable 3–5 ml/L en brotación.'),
('seca-de-la-encina','Evitar encharcamientos, heridas en el tronco y compactación del suelo. No hay tratamiento curativo eficaz; se puede apoyar con fosfitos potásicos 2–3 ml/L en riego o inyección.'),
('septoriosis','Rotación, eliminación de hojas manchadas y riego por goteo. Fitosanitarios Sipcam: cobre 3 ml/L preventivo o fungicida sistémico 1,5–2 ml/L cada 12 días en primavera húmeda.'),
('trips','Trampas azules y control biológico. Fitosanitarios Sipcam: abamectina 0,75–1 ml/L o piretrina natural 1–2 ml/L, 2–3 aplicaciones separadas 7 días.'),
('verticilosis','Rotación de cultivos, solarización y suelo bien drenado. No existe fitosanitario curativo: usar variedades resistentes y eliminar las plantas afectadas.'),
('podredumbre-apical','Riego regular y sin altibajos, y aporte de calcio. Producto Sipcam: corrector de calcio foliar 2–3 ml/L cada 10 días desde el cuajado; no es un problema fúngico, no usar fungicida.'),
('podredumbre-del-cuello','No enterrar el cuello, regar por surco y evitar encharcar. Fitosanitarios Sipcam: fungicida cúprico 3 ml/L regado al cuello, 2 aplicaciones separadas 15 días.'),
('podredumbre-del-fruto','Acolchado para que el fruto no toque el suelo húmedo y retirada de frutos afectados. Fitosanitarios Sipcam: cobre 3 ml/L o fungicida polivalente 1,5–2 ml/L, respetando el plazo de seguridad.'),
('procesionaria','Trampas de feromona en verano y anillos de captura en invierno. Fitosanitarios Sipcam: Bacillus thuringiensis 1–2 ml/L en septiembre–octubre, cuando las orugas son pequeñas; retirar los bolsones con protección.'),
('procesionaria-del-pino','Trampas de feromona, anillos de captura y retirada de bolsones. Fitosanitarios Sipcam: Bacillus thuringiensis 1–2 ml/L al inicio del otoño; en árboles grandes, tratamiento con pértiga o endoterapia.'),
('pudricion-de-raiz','Sustrato muy drenante, riegos espaciados y maceta con buen drenaje. Fitosanitarios Sipcam: fungicida de suelo 2 ml/L regado al cepellón tras retirar la tierra encharcada.')
) as v(slug, txt)
where p.slug = v.slug;